CREATE MATERIALIZED VIEW non_leaf_194 AS
SELECT n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role, mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, mc.id AS mc_id, mc.movie_id AS mc_movie_id, mc.company_id AS mc_company_id, mc.company_type_id AS mc_company_type_id, mc.note AS mc_note, cn.id AS cn_id, cn.name AS cn_name, cn.country_code AS cn_country_code, cn.imdb_id AS cn_imdb_id, cn.name_pcode_nf AS cn_name_pcode_nf, cn.md5sum AS cn_md5sum, ct.id AS ct_id, ct.kind AS ct_kind, kt.id AS kt_id, kt.kind AS kt_kind
FROM name AS n, title AS t, cast_info AS ci, role_type AS rt, movie_info AS mi1, movie_companies AS mc, company_name AS cn, company_type AS ct, kind_type AS kt
WHERE n.id = ci.person_id AND t.id = mc.movie_id AND t.id = ci.movie_id AND t.production_year <= 2015 AND t.production_year >= 1990 AND ci.movie_id = mc.movie_id AND ci.role_id = rt.id AND rt.role IN ('actress', 'composer', 'editor') AND mi1.movie_id = mc.movie_id AND mi1.info ~~* '%d%' AND mi1.info_type_id = 6 AND mc.company_id = cn.id AND cn.name ~~* '%ve%' AND ct.id = mc.company_type_id AND kt.id = t.kind_id AND kt.kind ~~* '%m%';